      if actor in ['u1','test_admin']:
       page.locator('#mkCompliance').check();page.locator('#mkComplianceNote').fill('SYN human review');save(page);check('authorized approval audited',state(page)['marketing']['campaigns'][-1]['approvedBy']==actor)
      else:close(page)
      page.locator('[data-expense="'+cid+'"]').click();page.locator('#mkAmount').fill('90');page.locator('#mkEvidence').fill('SYN invoice reference');save(page);check('actual spend distinct from budget and evidence preserved',state(page)['marketing']['campaigns'][-1]['expenses'][0]['amountCents']==9000)
      tab(page,'leads');page.locator('[data-attribution="mk-r1"]').click();page.locator('#mkSource').select_option('Website');page.locator('#mkCampaign').select_option(cid);page.locator('#mkConsent').select_option('granted');save(page);check('commercial consent requires evidence',page.locator('#mkError').inner_text()!='');page.locator('#mkConsentEvidence').fill('SYN consent');save(page);check('attribution updates original contact without duplicates',len(state(page)['requests'])==2 and state(page)['requests'][0]['marketing']['campaignId']==cid)
      page.locator('[data-id="mk-r1"] [data-lead-target]').select_option('Consulta marcada');page.locator('[data-lead="mk-r1"]').click();save(page);check('selector conversion updates original Call Center stage',state(page)['requests'][0]['stage']=='Marcado');page.locator('[data-id="mk-r1"] [data-lead-target]').select_option('Consulta realizada');page.locator('[data-lead="mk-r1"]').click();save(page);check('performed consultation requires confirmation evidence',page.locator('#mkError').inner_text()!='');page.locator('#mkEvidence').fill('SYN attendance document');save(page);check('performed consultation and history persisted',bool(state(page)['requests'][0]['marketing']['performedAt']) and len(state(page)['requests'][0]['history'])==3)
