      tab(page,'budgets');page.locator('#mkNewTarget').click();page.locator('#mkClinics').select_option('mk-a');page.locator('#mk_amountCents').fill('100');save(page);check('budget plan does not create spend',len(state(page)['marketing']['budgets'])==1 and len(state(page)['marketing']['campaigns'][-1]['expenses'])==1)
